import {
  ChangeDetectionStrategy,
  Component,
  booleanAttribute,
  computed,
  forwardRef,
  input,
  model,
  signal,
} from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';

@Component({
  selector: 'aevko-input-otp',
  standalone: true,
  templateUrl: './input-otp.component.html',
  styleUrl: './input-otp.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => AevkoInputOtp),
      multi: true,
    },
  ],
  host: {
    '[attr.data-disabled]': 'isDisabled() ? "true" : null',
    '[attr.data-invalid]': 'invalid() ? "true" : null',
  },
})
export class AevkoInputOtp implements ControlValueAccessor {
  readonly label = input.required<string>();
  readonly maxLength = input(6);
  readonly disabled = input(false, { transform: booleanAttribute });
  readonly invalid = input(false, { transform: booleanAttribute });
  readonly characters = input<RegExp>(/[0-9A-Za-z]/);
  readonly value = model('');
  protected readonly formDisabled = signal(false);
  protected readonly isDisabled = computed(() => this.disabled() || this.formDisabled());
  protected readonly slots = computed(() =>
    Array.from({ length: Math.max(1, this.maxLength()) }, (_, index) => this.value()[index] ?? ''),
  );
  private onChange: (value: string) => void = () => undefined;
  private onTouched: () => void = () => undefined;

  protected update(event: Event): void {
    const input = event.target as HTMLInputElement;
    const value = [...input.value]
      .filter((character) => {
        const characters = this.characters();
        characters.lastIndex = 0;
        return characters.test(character);
      })
      .join('')
      .slice(0, this.maxLength());
    input.value = value;
    this.value.set(value);
    this.onChange(value);
  }

  protected touch(): void {
    this.onTouched();
  }

  writeValue(value: string | null): void {
    this.value.set((value ?? '').slice(0, this.maxLength()));
  }

  registerOnChange(fn: (value: string) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(disabled: boolean): void {
    this.formDisabled.set(disabled);
  }
}

:host {
  display: inline-grid;
  position: relative;
}
input {
  cursor: text;
  inset: 0;
  opacity: 0;
  position: absolute;
  z-index: 1;
}
.slots {
  display: flex;
  gap: 0.5rem;
}
.slots span {
  align-items: center;
  background: var(--aevko-background, #fff);
  border: 1px solid var(--aevko-border-strong, #a1a1aa);
  border-radius: var(--aevko-radius, 0);
  color: var(--aevko-foreground, #09090b);
  display: inline-flex;
  font: 650 1rem/1 var(--aevko-font-mono, monospace);
  height: 2.75rem;
  justify-content: center;
  width: 2.5rem;
}
:host:focus-within .slots span[data-active='true'] {
  outline: 2px solid var(--aevko-focus, #a1a1aa);
  outline-offset: 1px;
}
:host([data-invalid='true']) .slots span {
  border-color: var(--aevko-danger, #3f3f3f);
}
:host([data-disabled='true']) {
  cursor: not-allowed;
  opacity: 0.5;
}
